export interface CuisineCategory {
  id: string;
  name: string;
  description: string;
  image: string;
  isHidden?: boolean;
  acknowledgementMessage?: string;
}

export type SuitableForTag = 
  | 'breakfast'
  | 'lunch'
  | 'dinner'
  | 'pre-workout'
  | 'post-workout'
  | 'light-meal'
  | 'high-protein'
  | 'low-carb';

