// --- Auth Functions ---
export const signUp = (email: string, password: string, firstName: string, lastName: string) => 
  supabase.auth.signUp({ 
    email, 
    password,
    options: {
      data: {
        first_name: firstName,
        last_name: lastName,
      }
    }
  });

export const signIn = (email: string, password: string) => 
