                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); setPromotedDishId(dish.id); }} 
                                                            className={`p-1.5 rounded-full transition-colors ${promotedDishId === dish.id ? 'bg-amber-100 text-amber-600' : 'hover:bg-gray-100 dark:hover:bg-white/10 text-gray-400'}`}
                                                            title="Feature on Landing Page"
                                                        >
                                                            <Star size={14} fill={promotedDishId === dish.id ? "currentColor" : "none"} />
                                                        </button>
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); toggleVisibility(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title={dish.isHidden ? "Show Dish" : "Hide Dish"}
                                                        >
                                                            {dish.isHidden ? <Eye size={14}/> : <EyeOff size={14}/>}
                                                        </button>
                                                        <button 
                                                            disabled={isSyncing}
                                                            onClick={(e) => { e.stopPropagation(); duplicateDish(dish); }} 
                                                            className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white disabled:opacity-50"
                                                            title="Duplicate Dish"
                                                        >
                                                            <Copy size={14}/>
                                                        </button>
                                                        <button onClick={() => setEditingDish(dish)} className="p-1.5 hover:bg-gray-100 dark:hover:bg-white/10 rounded-full transition-colors dark:text-white" title="Edit Dish"><Edit size={14}/></button>
                                                        <button onClick={() => removeDish(dish.id)} className="p-1.5 hover:bg-red-50 rounded-full transition-colors text-red-500" title="Delete Dish"><Trash2 size={14}/></button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </>
            )}
        </div>
    </div>
  );
};

