const ImageWithFallback = ({ src, alt, className }: { src: string; alt: string; className: string }) => {
  const [error, setError] = useState(false);
  const [loading, setLoading] = useState(true);

  return (
    <div className={`responsive-image bg-gray-50 dark:bg-zinc-800 ${className}`}>
      {loading && (
        <div className="absolute inset-0 flex items-center justify-center z-10">
          <Loader2 className="animate-spin text-gray-300 dark:text-zinc-600" size={32} />
        </div>
      )}
      <img
        src={error ? 'https://images.unsplash.com/photo-1504674900247-0877df9cc836?auto=format&fit=crop&q=80&w=800' : src}
        alt={alt}
        className={`transition-all duration-1000 ${loading ? 'opacity-0 scale-110' : 'opacity-100 scale-100'}`}
        onLoad={() => setLoading(false)}
        onError={() => {
          setError(true);
          setLoading(false);
        }}
      />
    </div>
  );
};

const NutritionStat = ({ 
  label, 
  value, 
  unit = 'g', 
  isLast = false, 
  colorClass = "text-black dark:text-white",
  icon: Icon,
  animate = false
}: { 
  label: string, 
  value: number | string, 
  unit?: string, 
  isLast?: boolean, 
  colorClass?: string,
  icon?: React.ElementType,
  animate?: boolean
}) => (
  <div className={`flex-1 flex flex-col items-center px-1 ${!isLast ? 'border-r border-gray-100 dark:border-white/10' : ''}`}>
    <div className="flex items-center gap-1.5 mb-2 group">
      {Icon && <Icon size={12} className={`${animate ? 'text-orange-500' : 'text-gray-200 dark:text-zinc-700'} group-hover:text-gray-400 transition-colors`} />}
      <div className="text-[9px] font-black uppercase tracking-[0.2em] text-gray-300 dark:text-zinc-600">{label}</div>
    </div>
    <div className={`text-2xl font-black leading-none tracking-tighter ${colorClass} ${animate ? 'animate-pulse' : ''}`}>
      {value}<span className="text-[10px] ml-0.5 opacity-40 font-bold lowercase tracking-normal">{unit}</span>
    </div>
  </div>
);

interface DishCardProps {
  dish: Dish;
