          </div>
        </div>
      </div>

      <div className="p-12 flex-1 flex flex-col">
        <div className="mb-10">
          <h3 className={`text-5xl font-black tracking-tighter text-[#1A1A1A] dark:text-zinc-100 mb-8 leading-none ${isClassic ? 'font-serif italic' : ''}`}>
            {dish.name}
          </h3>

          <div className="flex flex-wrap items-center gap-2 mb-10">
            {allComponents.map((item, idx) => (
              <span 
                key={idx} 
                className="px-4 py-2.5 bg-gray-50/80 dark:bg-white/5 border border-gray-100/50 dark:border-white/5 rounded-full text-[9px] font-black uppercase tracking-[0.2em] text-gray-400 dark:text-zinc-500 whitespace-nowrap shadow-sm hover:bg-white dark:hover:bg-white/10 hover:shadow-md hover:border-gray-200 transition-all duration-300"
              >
