      <X size={40} />
    </button>
    <img 
      src={src} 
      className="max-w-full max-h-full object-contain rounded-3xl shadow-2xl border border-white/10 animate-scale-in select-none" 
      alt="Full size"
      onClick={(e) => e.stopPropagation()}
    />
  </div>
);

