      </div>
    );
  }

  const currentCategoryDishes = dishes.filter(d => d.categoryId === viewState.currentCategory);
  const activeCategory = categories.find(c => c.id === viewState.currentCategory);

  return (
    <div 
      className="min-h-screen transition-all duration-700 ease-in-out font-['Inter'] selection:bg-black selection:text-white antialiased"
      style={{
        backgroundColor: theme === 'dark' ? '#09090b' : '#FBFBFB'
      }}
    >
      {zoomedImage && <Lightbox src={zoomedImage} onClose={() => setZoomedImage(null)} />}

      <header className="px-12 py-10 flex justify-between items-center bg-white/90 dark:bg-black/80 backdrop-blur-md border-b border-gray-100 dark:border-white/5 sticky top-0 z-50">
        <div className="flex-1">
          <button 
            onClick={() => setViewState((p: any) => ({...p, view: 'menu-overview'}))} 
            className="flex items-center gap-5 group"
          >
            <div className="w-14 h-14 flex items-center justify-center bg-gray-50 dark:bg-white/5 rounded-full group-hover:bg-black dark:group-hover:bg-white group-hover:text-white dark:group-hover:text-black transition-all duration-500 shadow-sm border border-transparent dark:border-white/10">
              <Home size={22} />
            </div>
            <div className="hidden md:block text-left">
              <span className="text-[10px] font-black uppercase tracking-widest block text-gray-400 mb-0.5">Return to</span>
              <span className="text-sm font-bold tracking-tight dark:text-white">Main Selection</span>
            </div>
          </button>
        </div>

        <div className="text-center flex-1">
          <h2 className={`text-xl font-black tracking-tight uppercase mb-2 dark:text-white ${isClassic ? 'font-serif italic' : ''}`}>
            {activeCategory?.name || appTitle}
          </h2>
          <div className="flex items-center justify-center gap-3">
            <div className="w-10 h-px bg-gray-200 dark:bg-white/10"></div>
            <span className="text-[10px] text-gray-400 dark:text-zinc-500 font-black uppercase tracking-[0.4em]">
              {currentCategoryDishes.length} Featured Creations
            </span>
            <div className="w-10 h-px bg-gray-200 dark:bg-white/10"></div>
          </div>
        </div>

        <div className="flex-1 flex justify-end"></div>
      </header>

      <main className="max-w-[1800px] mx-auto px-8 md:px-16 py-24">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-16 md:gap-24">
          {currentCategoryDishes.map((dish, idx) => (
            <DishCard 
              key={dish.id} 
              dish={dish} 
              isClassic={isClassic} 
              onImageClick={setZoomedImage}
              index={idx}
            />
          ))}
        </div>

        {currentCategoryDishes.length === 0 && (
          <div className="h-[60vh] flex flex-col items-center justify-center text-center animate-fade-in">
             <div className="p-10 bg-white/80 dark:bg-zinc-900 shadow-xl rounded-[3rem] border border-gray-100 dark:border-white/5 backdrop-blur">
                <Feather size={56} className="text-gray-200 dark:text-zinc-700" />
             </div>
             <h3 className="text-3xl font-black mb-4 tracking-tight dark:text-white">Curation in Progress</h3>
             <p className="text-gray-400 dark:text-zinc-500 max-w-sm text-lg font-light leading-relaxed">Our culinary team is currently perfecting this collection.</p>
          </div>
        )}
      </main>
    </div>
  );
};
